#include <iostream>
enum class Mode { idle, active, done };
enum class Event { begin, finish, reset };
bool send(Mode& m, Event e) {
    if (m == Mode::idle && e == Event::begin) {
        m = Mode::active; return true;
    }
    if (m == Mode::active && e == Event::finish) {
        m = Mode::done; return true;
    }
    if (m == Mode::done && e == Event::reset) {
        m = Mode::idle; return true;
    }
    return false; // Rejection leaves m unchanged.
}
int main() {
    Mode mode = Mode::idle;
    std::cout << std::boolalpha;
    std::cout << send(mode, Event::finish) << '\n';
    std::cout << send(mode, Event::begin) << '\n';
    std::cout << send(mode, Event::finish) << '\n';
    std::cout << send(mode, Event::reset) << '\n';
}

#include <iostream>
enum class Mode { idle, active, done };
bool shortcut_reset(Mode& mode) {
    mode = Mode::idle; // Wrong: accepts reset from every mode.
    return true;
}
bool contract_reset(Mode& mode) {
    if (mode != Mode::done) return false;
    mode = Mode::idle;
    return true;
}
int main() {
    Mode wrong = Mode::active;
    Mode right = Mode::active;
    std::cout << std::boolalpha;
    std::cout << "shortcut accepted: " << shortcut_reset(wrong) << '\n';
    std::cout << "contract accepted: " << contract_reset(right) << '\n';
    std::cout << "contract still active: " << (right == Mode::active) << '\n';
}
